
async function evaluateModel(modelName, yTest, yPred, yProba = null, history = null) {
    const response = await fetch('http://localhost:5000/evaluate/${modelName}', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
        },
        body: JSON.stringify({
            model_name: modelName,
            y_test: yTest,
            y_pred: yPred,
            // y_proba: yProba,
            // history: history,
        }),
    });

    if (!response.ok) {
        console.error('Error fetching evaluation data:', response.statusText);
        return;
    }

    const evaluationData = await response.json();
    displayEvaluationResults(evaluationData, modelName);
}

function displayEvaluationResults(data, modelName) {
    // Display classification report
    console.log('Classification Report:', data.classification_report || `MSE: ${data.mse}`);

    // Create Image Elements for each plot
    const container = document.getElementById('evaluation-results');
    container.innerHTML = ''; // Clear previous results

    const confusionMatrixImg = document.createElement('img');
    confusionMatrixImg.src = `./static/${modelName}_confusion_matrix.png`;
    confusionMatrixImg.alt = 'Confusion Matrix';
    container.appendChild(confusionMatrixImg);

    const rocCurveImg = document.createElement('img');
    rocCurveImg.src = `./static/${modelName}_roc_curve.png`;
    rocCurveImg.alt = 'ROC Curve';
    container.appendChild(rocCurveImg);

    const lossImg = document.createElement('img');
    lossImg.src = `./static/${modelName}_loss.png`;
    lossImg.alt = 'Training and Validation Loss';
    container.appendChild(lossImg);

    // Additional reporting information can be displayed in the console or on the webpage
}

evaluateModel(modelName, yTest, yPred);
